#!/usr/bin/env python3
"""Compile portable French/Spanish wording plus the Russian overlay, preserving native message flow/storage."""
import argparse
import json
from pathlib import Path
from single_screen_text import compile_messages, header, decode
ROOT = Path(__file__).resolve().parents[2]

def build(source, russian=None):
    sections = ['// SPDX-License-Identifier: GPL-2.0-or-later',
'// Generated by tools/mm3d/single_screen_localized.py. Do not edit.',
'#pragma once', '#include "mm3d/single_screen_text_data.h"']
    results = {}
    russian = ROOT/'resources/mm3d/rus/message/eu/eue.gmsg' if russian is None else russian
    for language, archive, array in [('french', 'usf', 'FrenchReplacements'),
('spanish', 'uss', 'SpanishReplacements'), ('russian', 'eue', 'RussianReplacements')]:
        spec = json.loads((ROOT/f'resources/mm3d/text/single-screen-{language}.json').read_text(encoding='utf-8'))
        source_path = russian if language == 'russian' else source/f'{archive}.gmsg'
        rows = compile_messages((source_path).read_bytes(), spec)
        for mid, _, _, data, tokens, _ in rows:
            assert decode(data) == tokens
            lines = 1
            for t in tokens:
                if t == (1,): lines += 1
                if t == (2,) or t == (0,):
                    if lines > 4: raise ValueError(f'{language} {mid:04x}: more than four lines')
                    lines = 1
        generated = header(rows)
        start = generated.index('inline constexpr')
        sections += ['namespace MM3D::SingleScreenText {',
                     generated[start:].replace(' Replacements', ' '+array)]
        results[language] = rows
    return '\n'.join(sections), results

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('source', type=Path)
    parser.add_argument('--russian-archive', type=Path, default=ROOT/'resources/mm3d/rus/message/eu/eue.gmsg')
    parser.add_argument('--header', type=Path, required=True)
    args = parser.parse_args()
    output, rows = build(args.source, args.russian_archive)
    args.header.write_text(output)
    print('Compiled', sum(map(len, rows.values())), 'localized replacements')
